<?php

/**
 * Runs once, from composer's post-create-project-cmd: gives a new project a working .env
 * and a JWT keypair.
 *
 *   .env  <- .env.example (every key in it is read by the framework)
 *   keys/ <- RSA keypair generated by `php stone setup --quiet`
 *
 * `stone setup --quiet` leaves an existing .env alone and only generates the keypair.
 *
 * An existing .env is never touched.
 */

chdir(dirname(__DIR__));

if (file_exists('.env')) {
    echo ".env already exists, leaving it and the keys alone\n";
    exit(0);
}

// .env holds secrets once filled in: owner read/write, group read (a container's PHP user), nobody else.
if (!copy('.env.example', '.env') || !chmod('.env', 0640)) {
    fwrite(STDERR, "\nERROR: could not create .env from .env.example (check that this directory is writable).\n");
    @unlink('.env');
    exit(1);
}
passthru(escapeshellarg(PHP_BINARY) . ' stone setup --quiet', $code);

if ($code !== 0 || !is_file('keys/jwt-private.pem') || !is_file('keys/jwt-public.pem')) {
    // Do not report success: without a keypair no token can be signed.
    fwrite(STDERR, "\nERROR: could not generate the JWT keypair (keys/jwt-private.pem, keys/jwt-public.pem).\n");
    fwrite(STDERR, "Run `php stone generate jwt` (needs the PHP openssl extension), then re-run your setup.\n");
    exit(1);
}

echo "\nCreated .env from .env.example and generated keys/jwt-*.pem.\n";
echo "Next: set JWT_ISSUER, the DB_GATEWAY_* values and your auth settings in .env, and your\n";
echo "sign-in page origin in src/config/allowed-origins.php (check with: php stone auth:check-origins).\n";
